#!/usr/bin/env python3
"""Bounded below-structure carrier trial; no complete barrier is asserted."""
import hashlib, json, math, subprocess, sys
from pathlib import Path
R=Path(__file__).resolve().parents[3]; O=Path(__file__).resolve().parent
expected={'project/mat/studies/warm-receiving-grid.json':'a5bff9f37b8d78dfb32359427314b4013fe8a45e','project/had/studies/open-north-loggia.json':'25faad2c4d40df2b7da7212f73808843a88d2f52','project/str/studies/sw-corner-station.json':'d5e2c7650a1ea278ed22cded58a81e046374c131'}
def blob(raw): return hashlib.sha1(f'blob {len(raw)}\0'.encode()+raw).hexdigest()
s={}
for p,h in expected.items():
 raw=(R/p).read_bytes(); assert blob(raw)==h and subprocess.check_output(['git','rev-parse','HEAD:'+p],cwd=R,text=True).strip()==h,(p,'changed or untracked'); s[p]=json.loads(raw)
w=s['project/mat/studies/warm-receiving-grid.json']['recipe']; h=s['project/had/studies/open-north-loggia.json']; t=s['project/str/studies/sw-corner-station.json']
assert w['floorZ']==[0,-15,-80,-280,-600] and w['warmGridSoffit']==-380 and w['AACZ']==[-605,-390] and w['mineralDPC']==[-765,-615]
assert h['shell']==12000 and h['court']==[4250,4250,3500,3500]
assert t['trial_pier']['pier_bounds_mm']==[262.5,262.5,562.5,562.5] and t['connector_sensitivity']['nominal_bar_bottom_top_mm']==[-990,6410]
plate=[262.5,262.5,562.5,562.5]; bay=[600,600,1600,1600]; points=[(600,600),(600,1600),(1600,600),(1600,1600)]
assert bay[0]-plate[2]==37.5 and bay[1]-plate[3]==37.5
bridge=[512.5,512.5,650,650]; assert plate[2]-bridge[0]==50 and bridge[2]-bay[0]==50
rho=7850; area=(2*40*4-4*4); sheetkg=1*1*.001*rho; railkg=4*area/1e6*rho; hangerkg=4*math.pi*(.008**2)/4*.324*rho; total=sheetkg+railkg+hangerkg
assert math.isclose(total,17.90648,abs_tol=.01)
assert -380-(-605)==225 and -605-(-765)==160
uplift=t['finite_roof_candidate']['partial_south_west_route']['uplift']
ux,uy=uplift['SW_node_resultant_xy_mm']; force=abs(uplift['SW_node_vertical_kN'])
tx=(ux-322.5)/180;ty=(uy-322.5)/180
weights=[(1-tx)*(1-ty),(1-tx)*ty,tx*(1-ty),tx*ty]
anchors=[(322.5,322.5),(322.5,502.5),(502.5,322.5),(502.5,502.5)]
assert all(v>=0 for v in weights) and math.isclose(sum(weights),1)
assert math.isclose(sum(weights[i]*anchors[i][0] for i in range(4)),ux) and math.isclose(sum(weights[i]*anchors[i][1] for i in range(4)),uy)
d={'status':'Finite near-SW panel and split-rod patch; whole barrier and structure fail admission','sources':expected,
 'datum_mm':{'field':[-605,-604],'patch':[-605,-602],'slab':[-280,-80],'insulation':[-600,-280],'warmGridBottom':-380,'AAC':[-605,-390],'mortar':[-615,-605],'mineralDPC':[-765,-615],'coldRC':[-1215,-765]},
 'patch':{'xy_mm':plate,'fourRodCentres_mm':t['connector_sensitivity']['bar_centres_mm'],'upperSplitRod_z_mm':[-602,6410],'lowerSplitRod_z_mm':[-990,-605],'fieldPatchJoin':'Hypothesised continuous butt weld around full 300-square plate. Upper/lower rods terminate on opposite patch faces; weld procedure must retain plate integrity.'},
 'partialUpliftEquilibrium':{'source':'STR partial outer-triangle roof route only; not whole corner', 'vertical_kN':-force,'resultantXY_mm':[ux,uy],'bilinearFractions':weights,'witnessTensions_kN':[force*v for v in weights],'limit':'This is only a nonnegative static equilibrium witness. Plate stiffness, welds, actual unilateral contact, other roof areas, wind, lateral actions, load combinations and node resistance are not demonstrated.'},
 'fieldBay':{'xy_mm':bay,'nominalPanel_mm':[1000,1000,1],'hangerAnchorsXY_mm':points,'hanger_mm':{'diameter':8,'slabSoffitZ':-280,'sheetTopZ':-604,'nominalLength':324},'frame_mm':{'equalAngleLeg':40,'thickness':4,'topZ':-564,'bottomZ':-604,'layout':'four perimeter rails, no shared-edge mass credit'},'grossMetalMass_kg':{'sheet':sheetkg,'fourRails':railkg,'fourHangers':hangerkg,'total':total},'gravity_kN_at_9p81':total*9.81/1000,'fourEqualReactions_kN_ideal':total*9.81/4000,'massScope':'Local gross self-weight only; excludes fixings, welds, returns, sheet overlap, insulation support, water, construction and pressure loads. Shared edges double-counted.'},
 'collision_and_installation':{'warmConcrete':'Field is 225 mm below −380 warm girder soffit and 160 mm above −765 cold top; it does not cut warm RC; split rods and bearing patch still change the structural route.','glass':'40 mm rail depth occupies −604..−564: glass from −280..−600 is intercepted over 36 mm of rail depth; hangers traverse the glass. No uncut 320 glass claim.','flange':'Panel near edge 600 is 37.5 from patch edge 562.5 in each axis. A 137.5-square connector at x/y512.5..650 overlaps each footprint 50×50 before cutting; trim to matching boundaries and continuously butt weld, with no unsealed lap credited. Actual corner cuts, support and inspection remain to design.','supports':'Four anchors into nominal slab underside; 324 mm vertical hangers through cut/retained glass fixed to upper angles; sheet welded to underside of bottom angle flanges by accessible edge seams, without through-field fixings. Anchor, reinforcement clash, bearing, fixity and void access unproved.','scope':'One square tests a layout, not evidence exact slab underside, access, services and anchors exist at every point.'},
 'decision':'FAIL as complete barrier: wall, court, doorway, grid, service and drainage perimeter, movement, supports, corrosion, 3D thermal route and repair are unresolved. Retain local geometry as a challenger, not approved waterproof/gas or structural design.'}
def out(name,body):
 p=O/name
 if '--check' in sys.argv: assert p.read_text()==body,name+' stale'
 else: p.write_text(body)
out('sw-corner-metal-carrier.json',json.dumps(d,indent=2)+'\n')
svg='''<svg xmlns="http://www.w3.org/2000/svg" width="420mm" height="210mm" viewBox="0 0 420 210"><rect width="420" height="210" fill="white"/><style>text{font-family:Arial,sans-serif;font-size:3px;fill:#203b47}.t{font-size:5px;font-weight:bold}.h{font-size:3.6px;font-weight:bold}.m{fill:none;stroke:#bb3e32;stroke-width:1}.rc{fill:#b8ccd5;stroke:#526772;stroke-width:.4}.glass{fill:#eadc9f;stroke:#526772;stroke-width:.3}.aac{fill:#b8d1b0;stroke:#526772;stroke-width:.3}</style><text x="10" y="11" class="t">SW below-structure metal field · finite carrier trial</text><text x="10" y="19">One 1 m panel and corner patch; complete field/perimeter and structural connections remain unresolved.</text><text x="10" y="30" class="h">A PLAN · one panel, not a house-wide grid</text><rect x="16" y="41" width="19.2" height="19.2" fill="#d1e0db" stroke="#bb3e32"/><rect x="37.6" y="62.6" width="64" height="64" fill="#f1f5f4" stroke="#bb3e32" stroke-width="1"/><rect x="32" y="57" width="8.8" height="8.8" fill="none" stroke="#a55d37" stroke-width=".5" stroke-dasharray="1 1"/><circle cx="37.6" cy="62.6" r="1.6"/><circle cx="101.6" cy="62.6" r="1.6"/><circle cx="37.6" cy="126.6" r="1.6"/><circle cx="101.6" cy="126.6" r="1.6"/><text x="10" y="136">Patch x/y262.5..562.5.</text><text x="10" y="142">Panel x/y600..1600; four hangers.</text><text x="10" y="148">37.5 gap each axis; connector x/y512.5..650.</text><text x="145" y="30" class="h">B SECTION · geometry at field and receiver</text><rect x="151" y="44" width="111" height="24" class="rc"/><text x="270" y="50">Warm slab −80..−280</text><rect x="151" y="68" width="111" height="36" class="glass"/><text x="270" y="78">320 glass −280..−600</text><rect x="151" y="68" width="26" height="11" class="rc"/><rect x="151" y="79" width="26" height="25" class="aac"/><text x="270" y="89">Local grid bottom −380</text><path d="M158,44 V103 M170,44 V103 M158,105 V125 M170,105 V125" stroke="#263e4a" stroke-width="1"/><path d="M151,104 H262" class="m"/><path d="M184,104 V98 H256 V104 M184,68 V98 M256,68 V98" fill="none" stroke="#325d70" stroke-width="1"/><text x="270" y="100">Field −605..−604</text><text x="270" y="106">40 rail cuts 36 mm glass locally</text><text x="270" y="112">324 hangers through glass</text><rect x="151" y="106" width="26" height="16" fill="#a697b5"/><text x="270" y="122">DPC −615..−765; cold RC below</text><text x="145" y="136">Frame anchors to slab underside; tabs welded to upper field.</text><text x="145" y="142">Split rods weld to opposite faces of plate; no field through-hole.</text><text x="10" y="165" class="h">C LOAD AND BOUNDARY</text><text x="10" y="172">1 mm sheet 7.85 kg + four 40×40×4 rails 9.55 kg + four Ø8 ×324 hangers 0.51 kg = 17.91 kg / nominal panel.</text><text x="10" y="179">0.176 kN gravity only; four equal 0.044 kN reactions are a sensitivity, not anchor design or loaded-capacity proof.</text><text x="10" y="188">Sheet seams, support anchors, slab steel, glass cuts, corrosion, movement, pressure, water/gas testing and repair are HOLDS.</text><text x="10" y="195">Court, walls, thresholds, services and all other bays are not mapped: not a complete barrier or selected system.</text></svg>'''
out('sw-corner-metal-carrier.svg',svg+'\n')
print(json.dumps({'mass_kg':total,'gravity_kN':total*9.81/1000,'status':d['status']}))
